// Design-token generator (DS-001, D-034).
//
// tokens.json and brand.json are the single source of truth. This module turns
// them into the web Tailwind theme and the Flutter token classes, and checks
// the rules that keep both apps consistent (valid values, WCAG AA contrast,
// the font family declared where it is loaded). No dependencies on purpose.

import { readFileSync } from 'node:fs';
import { join } from 'node:path';

export const GENERATED_NOTE =
  'GENERATED by packages/design_tokens/generate.mjs. Do not edit by hand.';

/** WCAG AA minimum contrast for normal-size text. */
export const WCAG_AA_NORMAL_TEXT = 4.5;

/** Output files, relative to the repository root. */
export const OUTPUT_PATHS = {
  css: 'apps/admin_web/src/app/tokens.css',
  brandTs: 'apps/admin_web/src/lib/brand.ts',
  dartColors: 'packages/flutter_shared/lib/src/tokens/app_colors.dart',
  dartTypography: 'packages/flutter_shared/lib/src/tokens/app_typography.dart',
  dartRadius: 'packages/flutter_shared/lib/src/tokens/app_radius.dart',
  dartSpacing: 'packages/flutter_shared/lib/src/tokens/app_spacing.dart',
  dartLayout: 'packages/flutter_shared/lib/src/tokens/app_layout.dart',
  dartBrand: 'packages/flutter_shared/lib/src/brand/app_brand.dart',
};

/** Files that must agree with the font token. */
export const FONT_CONSUMERS = {
  flutterPubspec: 'packages/flutter_shared/pubspec.yaml',
  webFonts: 'apps/admin_web/src/app/fonts.ts',
};

const HEX = /^#[0-9A-Fa-f]{6}$/;
const WEIGHTS = new Set([100, 200, 300, 400, 500, 600, 700, 800, 900]);
const IDENTIFIER = /^[a-z][A-Za-z0-9]*$/;
const TOKEN_NAME = /^[a-z][A-Za-z0-9]*(\.[a-z][A-Za-z0-9]*)*$/;

export function readJson(root, file) {
  return JSON.parse(readFileSync(join(root, file), 'utf8'));
}

/** `brand.primaryStrong` → `brandPrimaryStrong`. */
export function camelName(token) {
  return token
    .split('.')
    .map((part, index) =>
      index === 0 ? part : part[0].toUpperCase() + part.slice(1),
    )
    .join('');
}

/** `brand.primaryStrong` → `brand-primary-strong`. */
export function kebabName(token) {
  return token
    .split('.')
    .map((part) => part.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`))
    .join('-');
}

/** px → rem string without trailing zeros (16 px root). */
export function rem(px) {
  return `${Number((px / 16).toFixed(4))}rem`;
}

function channel(value) {
  const c = value / 255;
  return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
}

/** WCAG 2.x relative luminance of `#RRGGBB`. */
export function luminance(hex) {
  const n = Number.parseInt(hex.slice(1), 16);
  const r = channel((n >> 16) & 0xff);
  const g = channel((n >> 8) & 0xff);
  const b = channel(n & 0xff);
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

/** WCAG 2.x contrast ratio between two opaque colours. */
export function contrastRatio(a, b) {
  const la = luminance(a);
  const lb = luminance(b);
  return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
}

function positiveNumber(value) {
  return typeof value === 'number' && Number.isFinite(value) && value > 0;
}

function entries(group) {
  return Object.entries(group).filter(([key]) => !key.startsWith('$'));
}

/**
 * Returns a list of problems; an empty list means the tokens are valid.
 * `files` maps FONT_CONSUMERS keys to their text (omit to skip those checks).
 */
export function validate(tokens, brand, files = {}) {
  const problems = [];

  for (const [name, token] of entries(tokens.color)) {
    if (!TOKEN_NAME.test(name)) problems.push(`color "${name}": invalid name`);
    if (!HEX.test(token.value ?? '')) {
      problems.push(`color "${name}": value must be #RRGGBB`);
    }
  }

  for (const [fg, bg] of tokens.contrastPairs.pairs) {
    const a = tokens.color[fg]?.value;
    const b = tokens.color[bg]?.value;
    if (!a || !b) {
      problems.push(`contrast pair ${fg} on ${bg}: unknown colour token`);
      continue;
    }
    if (!HEX.test(a) || !HEX.test(b)) continue;
    const ratio = contrastRatio(a, b);
    if (ratio < WCAG_AA_NORMAL_TEXT) {
      problems.push(
        `contrast pair ${fg} on ${bg}: ${ratio.toFixed(2)}:1 is below WCAG AA (${WCAG_AA_NORMAL_TEXT}:1)`,
      );
    }
  }

  for (const [name, style] of entries(tokens.typography)) {
    if (!IDENTIFIER.test(name)) {
      problems.push(`typography "${name}": invalid name`);
    }
    if (!positiveNumber(style.size)) {
      problems.push(`typography "${name}": size must be a positive number`);
    }
    if (!WEIGHTS.has(style.weight)) {
      problems.push(`typography "${name}": weight must be 100–900 in 100s`);
    }
  }

  for (const group of ['radius', 'layout', 'container']) {
    for (const [name, token] of entries(tokens[group])) {
      if (!IDENTIFIER.test(name))
        problems.push(`${group} "${name}": invalid name`);
      if (!positiveNumber(token.value)) {
        problems.push(`${group} "${name}": value must be a positive number`);
      }
    }
  }

  for (const [name, value] of entries(tokens.breakpoint)) {
    if (!IDENTIFIER.test(name) || !positiveNumber(value)) {
      problems.push(`breakpoint "${name}": invalid`);
    }
  }

  const scale = tokens.spacing.scale;
  if (
    !scale.every(
      (step) => positiveNumber(step) && step % tokens.spacing.base === 0,
    )
  ) {
    problems.push(
      `spacing: every step must be a multiple of ${tokens.spacing.base}`,
    );
  }

  const { family, webVariable } = tokens.font;
  if (typeof family !== 'string' || family.trim() === '') {
    problems.push('font.family is required');
  }
  if (!/^--[a-z][a-z0-9-]*$/.test(webVariable ?? '')) {
    problems.push('font.webVariable must be a CSS custom property name');
  }
  if (files.flutterPubspec !== undefined) {
    const declared = new RegExp(
      `^\\s*- family: ${escapeRegExp(family)}\\s*$`,
      'm',
    );
    if (!declared.test(files.flutterPubspec)) {
      problems.push(
        `font "${family}" is not declared in ${FONT_CONSUMERS.flutterPubspec} (add its font files there)`,
      );
    }
  }
  if (
    files.webFonts !== undefined &&
    !files.webFonts.includes(`'${webVariable}'`)
  ) {
    problems.push(
      `${FONT_CONSUMERS.webFonts} must load the font with variable '${webVariable}'`,
    );
  }

  for (const [key, value] of entries(brand)) {
    if (typeof value !== 'string' || value.trim() === '') {
      problems.push(`brand "${key}" must be a non-empty string`);
    }
  }

  return problems;
}

function escapeRegExp(text) {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// ---------------------------------------------------------------------------
// Web (Tailwind CSS v4 theme and TypeScript brand constants)
// ---------------------------------------------------------------------------

export function renderCss(tokens) {
  const lines = [
    '/*',
    ` * ${GENERATED_NOTE}`,
    ' * Source: packages/design_tokens/tokens.json (docs/DESIGN_SYSTEM.md).',
    ' *',
    " * Tailwind's default colours, fonts, font sizes, radii, container sizes and",
    ' * breakpoints are reset so that only project tokens exist as utilities, e.g.',
    ' * `bg-brand-primary`, `text-text-secondary`, `text-heading1`, `rounded-medium`,',
    ' * `max-w-form`, `desktop:grid-cols-2`. Spacing keeps the 4 px multiplier.',
    ' */',
    '@theme {',
    '  --color-*: initial;',
  ];
  for (const [name, token] of entries(tokens.color)) {
    lines.push(`  --color-${kebabName(name)}: ${token.value.toLowerCase()};`);
  }
  lines.push(
    '',
    '  --font-*: initial;',
    `  --font-sans: var(${tokens.font.webVariable}), ${tokens.font.fallback};`,
    '',
    '  /* Sizes only; apply the weight from the design-system table with font-* utilities. */',
    '  --text-*: initial;',
  );
  for (const [name, style] of entries(tokens.typography)) {
    lines.push(`  --text-${kebabName(name)}: ${rem(style.size)};`);
  }
  lines.push('', '  --radius-*: initial;');
  for (const [name, token] of entries(tokens.radius)) {
    lines.push(
      `  --radius-${kebabName(name)}: ${token.value >= 999 ? `${token.value}px` : rem(token.value)};`,
    );
  }
  lines.push('', '  --container-*: initial;');
  for (const [name, token] of entries(tokens.container)) {
    lines.push(`  --container-${kebabName(name)}: ${rem(token.value)};`);
  }
  lines.push('', '  --breakpoint-*: initial;');
  for (const [name, value] of entries(tokens.breakpoint)) {
    lines.push(`  --breakpoint-${kebabName(name)}: ${rem(value)};`);
  }
  lines.push('}', '');
  return lines.join('\n');
}

function tsString(value) {
  return `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

export function renderBrandTs(brand) {
  const lines = [
    `// ${GENERATED_NOTE}`,
    '// Source: packages/design_tokens/brand.json. Working names until the product',
    '// name and logo are decided.',
    '',
    'export const BRAND = {',
  ];
  for (const [key, value] of entries(brand)) {
    lines.push(`  ${key}: ${tsString(value)},`);
  }
  lines.push('} as const;', '');
  return lines.join('\n');
}

// ---------------------------------------------------------------------------
// Flutter (Dart token classes)
// ---------------------------------------------------------------------------

const DART_LINE = 80;

function dartString(value) {
  return `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\$/g, '\\$')}'`;
}

/** A `static const` field, split after `=` like `dart format` when too long. */
function dartConst(type, name, expression) {
  const line = `  static const ${type} ${name} = ${expression};`;
  if (line.length <= DART_LINE) return [line];
  return [`  static const ${type} ${name} =`, `      ${expression};`];
}

function dartNumber(value) {
  return String(value);
}

function dartDoc(text) {
  return `  /// ${text.endsWith('.') ? text : `${text}.`}`;
}

function dartHeader(extra = []) {
  return [
    `// ${GENERATED_NOTE}`,
    '// Source: packages/design_tokens/tokens.json (docs/DESIGN_SYSTEM.md).',
    ...extra,
  ];
}

export function renderDartColors(tokens) {
  const lines = [
    ...dartHeader(),
    '',
    "import 'package:flutter/painting.dart';",
    '',
    '/// Colour tokens. Paint shade colours are catalogue data and never belong',
    '/// here.',
    'abstract final class AppColors {',
  ];
  const all = entries(tokens.color);
  all.forEach(([name, token], index) => {
    if (index > 0) lines.push('');
    lines.push(dartDoc(token.use));
    const argb = `0xFF${token.value.slice(1).toUpperCase()}`;
    lines.push(...dartConst('Color', camelName(name), `Color(${argb})`));
  });
  lines.push('}', '');
  return lines.join('\n');
}

export function renderDartTypography(tokens) {
  const lines = [
    ...dartHeader(),
    '',
    "import 'package:flutter/painting.dart';",
    '',
    '/// Typography tokens. The font family is applied by `AppTheme`, so the',
    '/// styles deliberately leave `fontFamily` unset.',
    'abstract final class AppTypography {',
    '  /// Bundled in the `flutter_shared` package (see its `pubspec.yaml`).',
    ...dartConst('String', 'fontFamily', dartString(tokens.font.family)),
    ...dartConst(
      'String',
      'fontPackage',
      dartString(tokens.font.flutterPackage),
    ),
  ];
  for (const [name, style] of entries(tokens.typography)) {
    lines.push(
      '',
      dartDoc(style.use),
      `  static const TextStyle ${name} = TextStyle(`,
      `    fontSize: ${dartNumber(style.size)},`,
      `    fontWeight: FontWeight.w${style.weight},`,
      '  );',
    );
  }
  lines.push('}', '');
  return lines.join('\n');
}

export function renderDartRadius(tokens) {
  const lines = [
    ...dartHeader(),
    '',
    '/// Corner-radius tokens.',
    'abstract final class AppRadius {',
  ];
  entries(tokens.radius).forEach(([name, token], index) => {
    if (index > 0) lines.push('');
    lines.push(
      dartDoc(token.use),
      ...dartConst('double', name, dartNumber(token.value)),
    );
  });
  lines.push('}', '');
  return lines.join('\n');
}

export function renderDartSpacing(tokens) {
  const lines = [
    ...dartHeader(),
    '',
    `/// ${tokens.spacing.base} px-based spacing scale. Use these values instead of`,
    '/// one-off spacing literals.',
    'abstract final class AppSpacing {',
  ];
  for (const step of tokens.spacing.scale) {
    lines.push(...dartConst('double', `s${step}`, dartNumber(step)));
  }
  for (const [name, token] of entries(tokens.layout)) {
    lines.push(
      '',
      dartDoc(token.use),
      ...dartConst('double', name, dartNumber(token.value)),
    );
  }
  lines.push('}', '');
  return lines.join('\n');
}

export function renderDartLayout(tokens) {
  const lines = [
    ...dartHeader(),
    '',
    '/// Content widths and breakpoints (logical pixels), shared with the web.',
    'abstract final class AppLayout {',
  ];
  const fields = [
    ...entries(tokens.container).map(([name, token]) => [
      `${name}MaxWidth`,
      token.value,
      token.use,
    ]),
    ...entries(tokens.breakpoint).map(([name, value]) => [
      `${name}Breakpoint`,
      value,
      `Width at which the ${name} layout starts`,
    ]),
  ];
  fields.forEach(([name, value, use], index) => {
    if (index > 0) lines.push('');
    lines.push(dartDoc(use), ...dartConst('double', name, dartNumber(value)));
  });
  lines.push('}', '');
  return lines.join('\n');
}

export function renderDartBrand(brand) {
  const lines = [
    `// ${GENERATED_NOTE}`,
    '// Source: packages/design_tokens/brand.json. Working names until the product',
    '// name and logo are decided.',
    '',
    '/// Product and app names shown in the apps.',
    'abstract final class AppBrand {',
  ];
  entries(brand).forEach(([key, value], index) => {
    if (index > 0) lines.push('');
    lines.push(...dartConst('String', key, dartString(value)));
  });
  lines.push('}', '');
  return lines.join('\n');
}

/** Every generated file as `{ path, content }`, paths relative to the root. */
export function renderAll(tokens, brand) {
  return [
    { path: OUTPUT_PATHS.css, content: renderCss(tokens) },
    { path: OUTPUT_PATHS.brandTs, content: renderBrandTs(brand) },
    { path: OUTPUT_PATHS.dartColors, content: renderDartColors(tokens) },
    {
      path: OUTPUT_PATHS.dartTypography,
      content: renderDartTypography(tokens),
    },
    { path: OUTPUT_PATHS.dartRadius, content: renderDartRadius(tokens) },
    { path: OUTPUT_PATHS.dartSpacing, content: renderDartSpacing(tokens) },
    { path: OUTPUT_PATHS.dartLayout, content: renderDartLayout(tokens) },
    { path: OUTPUT_PATHS.dartBrand, content: renderDartBrand(brand) },
  ];
}
